<div class="page-header"><div><p class="eyebrow">Dienstbuch</p><h1>Suche</h1><p>Kombinierbare Filter über die Dienstbucheinträge des aktiven Standorts.</p></div></div>
<div class="panel"><form method="get" action="<?= e(url('dutybook/search')) ?>" class="form-grid"><label>Von<input type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>Bis<input type="date" name="to" value="<?= e($filters['to']) ?>"></label><label>Schicht<select name="shift_id"><option value="">Alle</option><?php foreach($shifts as $x):?><option value="<?= (int)$x['id'] ?>" <?= (int)$filters['shift_id']===(int)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Alle</option><?php foreach(['open'=>'Offen','in_progress'=>'In Bearbeitung','done'=>'Erledigt','handover'=>'Zur Übergabe'] as $v=>$l):?><option value="<?= e($v) ?>" <?= $filters['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label>Kategorie<select name="category_id"><option value="">Alle</option><?php foreach($categories as $x):?><option value="<?= (int)$x['id'] ?>" <?= (int)$filters['category_id']===(int)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Ereignisart<select name="event_type_id"><option value="">Alle</option><?php foreach($eventTypes as $x):?><option value="<?= (int)$x['id'] ?>" <?= (int)$filters['event_type_id']===(int)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Ersteller<select name="creator_id"><option value="">Alle</option><?php foreach($users as $x):?><option value="<?= (int)$x['id'] ?>" <?= (int)$filters['creator_id']===(int)$x['id']?'selected':'' ?>><?= e($x['last_name'].', '.$x['first_name']) ?></option><?php endforeach;?></select></label><label>Beteiligter Mitarbeiter<select name="staff_id"><option value="">Alle</option><?php foreach($users as $x):?><option value="<?= (int)$x['id'] ?>" <?= (int)$filters['staff_id']===(int)$x['id']?'selected':'' ?>><?= e($x['last_name'].', '.$x['first_name']) ?></option><?php endforeach;?></select></label><label class="span-2">Volltext<input type="search" name="q" value="<?= e($filters['q']) ?>"></label><label class="check-row"><input type="checkbox" name="attachments" value="1" <?= $filters['attachments']?'checked':'' ?>><span>Nur mit Anhängen</span></label><div class="form-actions"><button class="button primary" type="submit">Suchen</button></div></form></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Schicht</th><th>Ereignis</th><th>Status</th><th>Sachverhalt</th><th></th></tr></thead><tbody><?php foreach($result['items'] as $entry):?><tr><td><?= e(format_datetime($entry['occurred_at'])) ?></td><td><?= e($entry['shift_name']??'–') ?></td><td><?= e($entry['event_type_name']??'Automatisch') ?></td><td><span class="badge status-<?= e($entry['status']) ?>"><?= e($entry['status']) ?></span></td><td><?= e(mb_strimwidth($entry['facts'],0,120,'…')) ?></td><td><a class="button ghost compact" href="<?= e(url('dutybook/'.$entry['id'])) ?>">Öffnen</a></td></tr><?php endforeach;?><?php if($result['items']===[]):?><tr><td colspan="6" class="empty">Keine Treffer.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><span><?= (int)$result['total'] ?> Treffer</span><span>Seite <?= (int)$result['page'] ?> / <?= (int)$result['pages'] ?></span></div></div>
